import { useState } from 'react';

// ✅ Define components at the TOP LEVEL so they keep a stable identity.
function Profile() {
  const [likes, setLikes] = useState(0);
  return <button onClick={() => setLikes(likes + 1)}>♥ {likes}</button>;
}

export default function App() {
  // ❌ If Profile were defined INSIDE App, React would create a new function
  //    every render, remount it, and reset its `likes` on each App re-render.
  return (
    <div>
      <Profile />
      <Profile />
    </div>
  );
}
