export default function App() {
  const [a, setA] = useState(0);
  const [b, setB] = useState(0);
  let renders = 0;
  renders++; // increments once per render — batching keeps it to one per click
  function bump() {
    setA(x => x + 1);
    setB(x => x + 1); // both updates -> a single re-render
  }
  return (
    <div>
      <p>a={a} b={b}</p>
      <p>render count this mount cycle: {renders}</p>
      <button onClick={bump}>bump both</button>
    </div>
  );
