react-test-001.example:
```tsx
import { test, expect } from '@jest/globals';
import { render, screen } from '@testing-library/react';

function Greeting({ name }: { name: string }) {
  return <h1>Hello, {name}!</h1>;
}

test('shows the greeting the user would read', () => {
  render(<Greeting name="Ada" />);
  // Assert on visible output, not internal state.
  expect(screen.getByRole('heading', { name: 'Hello, Ada!' })).toBeTruthy();
});
```

react-test-002.example:
```tsx
import { test, expect } from '@jest/globals';
import { render, screen } from '@testing-library/react';

function Form() {
  return <form><label>Email <input /></label><button>Submit</button></form>;
}

test('getByRole / queryByRole', () => {
  render(<Form />);
  expect(screen.getByRole('button', { name: 'Submit' })).toBeTruthy(); // exists -> getBy
  expect(screen.queryByRole('alert')).toBeNull();                       // absent -> queryBy
});
```

react-test-mcq-001.example:
```tsx
import { test, expect } from '@jest/globals';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { useState } from 'react';

function Counter() {
  const [n, setN] = useState(0);
  return <button onClick={() => setN(n + 1)}>count {n}</button>;
}

test('user-event simulates a real click', async () => {
  render(<Counter />);
  await userEvent.click(screen.getByRole('button'));
  expect(screen.getByRole('button').textContent).toBe('count 1');
});
```

react-test-003.example:
```tsx
import { test, expect } from '@jest/globals';
import { render, screen } from '@testing-library/react';
import { useState, useEffect } from 'react';

function LateMessage() {
  const [msg, setMsg] = useState('');
  useEffect(() => { const id = setTimeout(() => setMsg('done'), 10); return () => clearTimeout(id); }, []);
  return <p>{msg}</p>;
}

test('waits for async UI', async () => {
  render(<LateMessage />);
  expect(await screen.findByText('done')).toBeTruthy(); // retries until it appears
});
```

react-test-004.example:
```tsx
import { test, expect, jest } from '@jest/globals';
import { render, screen } from '@testing-library/react';
import { useEffect, useState } from 'react';

// Stand-in for a mocked API function (jest.mock('./api') works the same way).
const fetchUser = jest.fn<() => Promise<string>>().mockResolvedValue('Ada');

function Profile() {
  const [name, setName] = useState('');
  useEffect(() => { fetchUser().then(setName); }, []);
  return <p>{name || 'loading…'}</p>;
}

test('renders the mocked user', async () => {
  render(<Profile />);
  expect(await screen.findByText('Ada')).toBeTruthy();
});
```

react-test-005.example:
```tsx
import { test, expect } from '@jest/globals';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { useState } from 'react';

function Toggle() {
  const [on, setOn] = useState(false);
  return <button onClick={() => setOn(o => !o)}>{on ? 'ON' : 'OFF'}</button>;
}

test('asserts visible output, not internal state', async () => {
  render(<Toggle />);
  await userEvent.click(screen.getByRole('button'));
  expect(screen.getByRole('button').textContent).toBe('ON'); // what the user sees
});
```

react-test-mcq-002.example:
```tsx
import { test, expect } from '@jest/globals';
import { render, screen } from '@testing-library/react';
import { useEffect, useState } from 'react';

function Async() {
  const [v, setV] = useState('');
  useEffect(() => { Promise.resolve().then(() => setV('ready')); }, []);
  return <p>{v}</p>;
}

test('await the async update to avoid the act() warning', async () => {
  render(<Async />);
  // Without awaiting, the setV happens after the test -> act warning.
  expect(await screen.findByText('ready')).toBeTruthy();
});
```

