```tsx
import { useState } from 'react';

export default function App() {
  const [value, setValue] = useState('');
  // Extracted handler -> annotate with React.ChangeEvent<HTMLInputElement>.
  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    setValue(e.target.value); // e.target.value is typed as string
  }
  return <input value={value} onChange={handleChange} />;
}
```

react-types-003.example:
```tsx
import { useState } from 'react';

type User = { id: number; name: string };

export default function App() {
  // Without <User | null>, TS infers `null` and setUser(user) would error.
  const [user, setUser] = useState<User | null>(null);
  return (
    <div>
      <button onClick={() => setUser({ id: 1, name: 'Ada' })}>load</button>
      <p>{user ? user.name : 'no user'}</p>
    </div>
  );
}
```

react-types-004.example:
```tsx
// The modern, compile-time equivalent of PropTypes is just a TS type:
type ButtonProps = {
  label: string;       // required (was PropTypes.string.isRequired)
  disabled?: boolean;  // optional (was PropTypes.bool)
};

function Button({ label, disabled = false }: ButtonProps) {
  return <button disabled={disabled}>{label}</button>;
}

export default function App() {
  return <Button label="Save" />;
}
```

react-types-mcq-002.example:
```tsx
import type { ReactNode } from 'react';

type ListProps<T> = { items: T[]; renderItem: (item: T) => ReactNode };

function List<T>({ items, renderItem }: ListProps<T>) {
  return <ul>{items.map((item, i) => <li key={i}>{renderItem(item)}</li>)}</ul>;
}

export default function App() {
  // T is inferred as { id: number; name: string } — renderItem is fully typed.
  const users = [{ id: 1, name: 'Ada' }, { id: 2, name: 'Linus' }];
  return <List items={users} renderItem={u => <strong>{u.name}</strong>} />;
}
```

react-types-005.example:
```tsx
import { createContext, useContext } from 'react';

type AuthValue = { user: string };
const AuthContext = createContext<AuthValue | undefined>(undefined);

function useAuth(): AuthValue {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error('useAuth must be used within <AuthContext.Provider>');
  return ctx; // narrowed to AuthValue here
}

function Profile() {
  const { user } = useAuth();
  return <p>Hello {user}</p>;
}

export default function App() {
  return (
    <AuthContext.Provider value={{ user: 'Ada' }}>
      <Profile />
    </AuthContext.Provider>
  );
}
```

