react-vdom-003.example:
```tsx
import { useState } from 'react';

function Child() {
  const [text, setText] = useState('');
  return <input value={text} onChange={e => setText(e.target.value)} placeholder="type me" />;
}

export default function App() {
  const [span, setSpan] = useState(false);
  // Switching the wrapper type div<->span remounts Child and clears its input.
  const Wrapper = span ? 'span' : 'div';
  return (
    <div>
      <button onClick={() => setSpan(s => !s)}>toggle wrapper ({Wrapper})</button>
      <Wrapper><Child /></Wrapper>
    </div>
  );
}
```

