```tsx
import { useState } from 'react';

export default function App() {
  const [rows, setRows] = useState([{ id: 'a', n: 'A' }, { id: 'b', n: 'B' }]);
  // key={r.id} keeps each input's text with its row when reversed.
  return (
    <div>
      <button onClick={() => setRows(r => [...r].reverse())}>reverse</button>
      {rows.map(r => <div key={r.id}>{r.n}: <input placeholder={r.n} /></div>)}
    </div>
  );
}
```

