react-vdom-006.example:
```tsx
import { useState } from 'react';

export default function App() {
  const [a, setA] = useState(0);
  const [b, setB] = useState(0);
  // Even inside a timeout (React 18+), these are batched into one re-render.
  const bumpLater = () => setTimeout(() => { setA(x => x + 1); setB(x => x + 1); }, 200);
  return <button onClick={bumpLater}>a={a} b={b}</button>;
}
```

