react-vdom-007.example:
```tsx
import { useState } from 'react';

function ProfileForm() {
  const [name, setName] = useState('');
  return <input value={name} onChange={e => setName(e.target.value)} placeholder="name" />;
}

export default function App() {
  const [userId, setUserId] = useState(1);
  // Changing key remounts ProfileForm -> its input clears for the new user.
  return (
    <div>
      <button onClick={() => setUserId(id => id + 1)}>next user (#{userId})</button>
      <ProfileForm key={userId} />
    </div>
  );
}
```
